const API_BASE = (import.meta.env.VITE_API_BASE_URL || 'https://crop-mind-api.vercel.app/api').replace(/\/$/, '');
const POLL_MS = Math.max(5000, Number(import.meta.env.VITE_LIVE_POLL_INTERVAL_MS) || 15000);
const AppContext = createContext(null);
