async function request(path, { method = 'GET', body, headers = {}, auth = true, retry = true } = {}) {
  const token = sessionStorage.getItem('cm_access_token');
  const opts = { method, credentials: 'include', headers: { Accept: 'application/json', ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}), ...(auth && token ? { Authorization: `Bearer ${token}` } : {}), ...headers }, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) };
  let res = await fetch(API_BASE + path, opts);
  if (res.status === 401 && auth && retry) {
    try {
      const refresh = await fetch(API_BASE + '/auth/refresh', { method: 'POST', credentials: 'include', headers: { Accept: 'application/json' } });
      if (refresh.ok) {
        const data = await refresh.json();
        if (data.access_token) sessionStorage.setItem('cm_access_token', data.access_token);
        if (data.accessToken) sessionStorage.setItem('cm_access_token', data.accessToken);
        const token2 = sessionStorage.getItem('cm_access_token');
        res = await fetch(API_BASE + path, { ...opts, headers: { ...opts.headers, ...(token2 ? { Authorization: `Bearer ${token2}` } : {}) } });
      }
    } catch { /* auth error will be shown below */ }
  }
  if (res.status === 204 || res.status === 304) return null;
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = { detail: text }; }
  if (!res.ok) {
    const err = new Error(data?.detail || data?.message || `Request failed (${res.status})`);
    err.status = res.status;
    throw err;
  }
  return data;
}
