function AppProvider({ children }) {
  const [theme,setTheme] = useState(localStorage.getItem('cm_theme') || 'light');
  const [user,setUser] = useState(null);
  const [authLoading,setAuthLoading] = useState(true);
  const [toast,setToast] = useState(null);
  const [refreshKey,setRefreshKey] = useState(0);
  useEffect(()=>{ document.documentElement.classList.toggle('dark',theme==='dark'); localStorage.setItem('cm_theme',theme); },[theme]);
  useEffect(()=>{ let active=true; request('/auth/me').then(data=>{ if(active) setUser(data?.user || data || null); }).catch(()=>{ if(active) setUser(null); }).finally(()=>{if(active)setAuthLoading(false)}); return ()=>{active=false}; },[]);
  const notify = (message,kind='success') => { setToast({message,kind}); window.setTimeout(()=>setToast(null),3600); };
  const value = {theme,setTheme,user,setUser,authLoading,toast,notify,refreshKey,refresh:()=>setRefreshKey(x=>x+1)};
  return <AppContext.Provider value={value}>{children}{toast && <div className={`toast toast-${toast.kind}`} role="status">{toast.kind==='error'?<CircleAlert size={18}/>:<CheckCircle2 size={18}/>} {toast.message}</div>}</AppContext.Provider>;
}
