function useLiveQuery(path, {enabled=true, interval=POLL_MS}={}) {
  const {refreshKey} = useApp();
  const [state,setState] = useState({data:null,loading:true,error:null,live:false,updatedAt:null});
  useEffect(()=>{
    if(!enabled){setState(s=>({...s,loading:false}));return;}
    let stopped=false, timer=null, failures=0, etag='', delay=interval;
    const run=async()=>{
      if(document.hidden){timer=window.setTimeout(run,interval);return;}
      try{
        const headers=etag?{'If-None-Match':etag}:{};
        const token=sessionStorage.getItem('cm_access_token');
        const res=await fetch(API_BASE+path,{credentials:'include',headers:{Accept:'application/json',...headers,...(token?{Authorization:`Bearer ${token}`}:{})}});
        if(res.status===401 && token){await request(path); failures=0;}
        else if(res.status===304){failures=0;setState(s=>({...s,loading:false,error:null,live:true}));}
        else if(!res.ok) throw new Error(`API returned ${res.status}`);
        else {const data=await res.json();etag=res.headers.get('ETag')||etag;failures=0;setState({data,loading:false,error:null,live:true,updatedAt:new Date()});}
        delay=interval;
      }catch(error){failures+=1;delay=Math.min(interval*8,interval*Math.pow(2,Math.min(failures,3)));setState(s=>({...s,loading:false,error:error.message,live:false}));}
      if(!stopped)timer=window.setTimeout(run,delay);
    };
    const onVisibility=()=>{if(!document.hidden&&timer){clearTimeout(timer);run();}};
    document.addEventListener('visibilitychange',onVisibility);run();
    return()=>{stopped=true;clearTimeout(timer);document.removeEventListener('visibilitychange',onVisibility);};
  },[path,enabled,interval,refreshKey]);
  return state;
}
function normalizeSummary(d){return d?.summary||d?.data||d||{};}
function Metric({icon:Icon,label,value,detail,tone='green',trend}) {return <Card className="metric-card"><div className={`metric-icon metric-${tone}`}><Icon size={19}/></div><div className="metric-label">{label}</div><div className="metric-value">{value??'—'}</div><div className="metric-detail">{trend&&<span className="trend"><ArrowUpRight size={13}/>{trend}</span>}{detail}</div></Card>;}
function TrendChart({data=demoTrend,title='Weekly recommendation activity',subtitle='Illustrative activity only'}) {return <Card className="chart-card"><div className="card-head"><div><h3>{title}</h3><p>{subtitle}</p></div><span className="mini-pill"><Activity size={13}/> Demo data</span></div><div className="chart-area"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id="trendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#9BCB4B" stopOpacity={.26}/><stop offset="100%" stopColor="#9BCB4B" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="4 5" vertical={false} stroke="var(--line)"/><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'var(--muted)'}}/><YAxis tickLine={false} axisLine={false} tick={{fontSize:11,fill:'var(--muted)'}}/><Tooltip contentStyle={{borderRadius:12,border:'1px solid var(--line)',background:'var(--surface)',color:'var(--text)'}}/><Area type="monotone" dataKey="n" name="Activity (demo)" stroke="#2F6B3F" strokeWidth={2.5} fill="url(#trendFill)" activeDot={{r:5}}/></AreaChart></ResponsiveContainer></div><p className="chart-foot"><Info size={14}/> Demo data is illustrative and does not represent live user traffic.</p></Card>;}
function CropTile({crop,index=0,onSelect}) {const score=Number(crop.score??crop.suitability_score??0);const cropName=crop.crop_name||crop.name||'Crop profile';return <motion.article className="crop-tile" initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:index*.05}}><div className="crop-symbol">{cropName.slice(0,1).toUpperCase()}</div><div className="crop-tile-main"><div className="crop-tile-title"><h3>{cropName}</h3><span className="rank-chip">#{index+1}</span></div><p>{crop.category||crop.suitability||'Suitability profile'}</p><div className="score-track"><span style={{width:`${Math.min(100,Math.max(0,score))}%`}}/></div><small>{crop.confidence?.label||crop.confidence_label||'Confidence varies'} confidence · {crop.confidence?.completeness_pct??crop.data_completeness_pct??'—'}% complete</small></div><div className="crop-score"><b>{score.toFixed(0)}</b><small>/100</small></div>{onSelect&&<button className="tile-action" onClick={()=>onSelect(crop)} aria-label={`Open ${cropName}`}><ChevronRight/></button>}</motion.article>;}
function Disclaimer(){return <div className="disclaimer"><ShieldCheck size={17}/><p><b>Decision support, not a guarantee.</b> CropMind scores compare your inputs with crop profiles. They are not probabilities of yield or success. Validate with a current soil test and a local agronomist before planting.</p></div>;}


